    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // NOTE: Replace this with a real database call in production.
    // Never expose sensitive fields (e.g., passwords, tokens) in responses.
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
