  try {
    // Example: validate an optional `?limit` query param
    const rawLimit = req.query.limit;
    let limit;

    if (rawLimit !== undefined) {
      limit = parseInt(rawLimit, 10);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return res.status(400).json({
          error: 'Invalid "limit" parameter. Must be an integer between 1 and 100.',
        });
      }
    }

    // In a real app these would come from a database; emails are omitted
    // here to avoid over-exposing PII to unauthenticated callers.
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    const result = limit ? users.slice(0, limit) : users;
    res.json(result);
  } catch (err) {
    next(err); // forward unexpected errors to the global handler
  }
});

// ---------------------------------------------------------------------------
// 5. 404 handler – must be registered after all valid routes
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

