'use strict';

// Simple application with security best practices applied
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ---------------------------------------------------------------------------
// 1. SECURITY HEADERS — helmet sets ~15 security-related HTTP headers
//    (e.g. X-Content-Type-Options, X-Frame-Options, Strict-Transport-Security)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. REQUEST BODY PARSING — limits payload size to prevent large-body DoS
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. RATE LIMITING — prevents brute-force and DoS attacks
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max 100 requests per window per IP
  standardHeaders: true,     // return rate limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// Mock data (replace with a real database in production)
// ---------------------------------------------------------------------------
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ---------------------------------------------------------------------------
// 4. INPUT VALIDATION HELPER
//    Centralising validation logic keeps routes clean and rules consistent.
// ---------------------------------------------------------------------------

/**
 * Validates that `value` is a safe, positive integer string.
 * Rejects floats, negative numbers, and non-numeric strings.
 * @param {string} value
 * @returns {number|null} Parsed integer, or null if invalid.
 */
function parsePositiveInt(value) {
  if (!/^\d+$/.test(value)) return null;      // digits only — no signs, dots, etc.
  const n = Number(value);
  return Number.isInteger(n) && n > 0 ? n : null;
}

// ---------------------------------------------------------------------------
// ROUTES
// ---------------------------------------------------------------------------

// GET /health — basic liveness probe
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users — return all users (sensitive fields stripped)
app.get('/users', (req, res) => {
  // Only expose the fields clients actually need
  const safeUsers = USERS.map(({ id, name }) => ({ id, name }));
  res.json(safeUsers);
});

// GET /users/:id — return a single user by ID
app.get('/users/:id', (req, res) => {
  // 5. INPUT VALIDATION — reject anything that is not a positive integer
  const userId = parsePositiveInt(req.params.id);
  if (userId === null) {
    return res.status(400).json({ error: 'Invalid user ID. Must be a positive integer.' });
  }

  const user = USERS.find((u) => u.id === userId);
  if (!user) {
    return res.status(404).json({ error: 'User not found.' });
  }

  // Return only safe fields — never expose passwords, tokens, internal keys, etc.
  const { id, name } = user;
  res.json({ id, name });
});

// ---------------------------------------------------------------------------
// 6. 404 HANDLER — catches requests to undefined routes
//    Must be registered AFTER all valid routes.
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ---------------------------------------------------------------------------
// 7. GLOBAL ERROR HANDLER — catches errors passed via next(err) or thrown
//    inside async route handlers (when wrapped with a helper or using
//    Express 5's built-in async support).
//    Four-argument signature is required by Express to recognise this as an
//    error handler.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for debugging …
  console.error('[ERROR]', err.stack || err.message);

  // … but never leak internal details to the client.
  const statusCode = err.status || err.statusCode || 500;
  res.status(statusCode).json({
    error: statusCode === 500 ? 'An unexpected error occurred.' : err.message,
  });
});

// ---------------------------------------------------------------------------
// SERVER STARTUP
// ---------------------------------------------------------------------------

// 8. ENVIRONMENT CONFIG — read port from environment so the same code runs
//    in development, staging, and production without modification.
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// 9. GRACEFUL SHUTDOWN — allows in-flight requests to complete before exiting,
//    which avoids dropped connections during deployments or restarts.
function shutdown(signal) {
  console.log(`\nReceived ${signal}. Shutting down gracefully…`);
  server.close(() => {
    console.log('HTTP server closed.');
    process.exit(0);
  });

  // Force-kill if shutdown takes longer than 10 s
  setTimeout(() => {
    console.error('Shutdown timed out. Forcing exit.');
    process.exit(1);
  }, 10_000).unref();
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

module.exports = app;

